const wf = $getWorkflowStaticData('global');
const cfg = $('Config Center').first().json;

// ---- YouTube Trending ----
let ytTitles = [];
try {
  const ytRes = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://www.googleapis.com/youtube/v3/videos',
    qs: {
      part: 'snippet,statistics',
      chart: 'mostPopular',
      regionCode: 'US',
      maxResults: 2,
      key: cfg.youtubeDataApiKey
    },
    json: true,
    timeout: 20000
  });
  const items = (ytRes && ytRes.items) || [];
  ytTitles = items.map(v => v.snippet && v.snippet.title).filter(Boolean).slice(0, 20);
} catch (e) {
  ytTitles = [];
}

// ---- Google Trends RSS ----
let gTerms = [];
try {
  const gRes = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://trends.google.com/trending/rss?geo=US',
    timeout: 15000
  });
  const raw = String(gRes || '');
  const matches = [...raw.matchAll(/<title>(.*?)<\/title>/g)].map(m => m[1]).filter(Boolean);
  gTerms = matches.filter(t => !/daily search trends/i.test(t)).slice(0, 20);
} catch (e) {
  gTerms = [];
}

// ---- Obscure Wikipedia topics (merged in from the old Fetch Obscure Wiki Topics + Extract Wiki Topics pair) ----
let obscureTopics = [];
try {
  const wikiRes = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://en.wikipedia.org/w/api.php',
    qs: { action: 'query', list: 'random', rnnamespace: 0, rnlimit: 5, format: 'json' },
    json: true,
    timeout: 10000
  });
  const list = (wikiRes && wikiRes.query && wikiRes.query.random) || [];
  const BAD = /^(list of|category:|template:|disambiguation|index of)/i;
  obscureTopics = list.map(x => x.title).filter(Boolean).filter(t => !BAD.test(t));
} catch (e) {
  obscureTopics = [];
}

// ---- Combine + store for downstream nodes (Build Exclusion Prompt reads wf.trendingContext) ----
const combined = [...new Set([...ytTitles, ...gTerms])].filter(Boolean).slice(0, 15);
wf.trendingContext = combined.join(' | ');

return [{
  json: {
    youtubeTrends: ytTitles,
    googleTrends: gTerms,
    trendingContextStored: wf.trendingContext,
    obscureTopics: obscureTopics.join(', ')
  }
}];

const rows = items.map(i => i.json).filter(Boolean);

function norm(s){ return String(s||'').toLowerCase().trim(); }

const usedTitles   = rows.map(r => norm(r.title)).filter(Boolean);
const usedTopics   = rows.map(r => norm(r.topic)).filter(Boolean);
const usedHooks    = rows.map(r => norm(r.hook)).filter(Boolean);
const usedEntities = rows.map(r => norm(r.entities)).filter(Boolean);
const usedDescs    = rows.map(r => norm(r.description)).filter(Boolean);

const categories = ['space mysteries & unexplained phenomena','deep ocean mysteries','forgotten civilizations','strange physics phenomena','medical mysteries & rare conditions','cold war secret operations','archaeological discoveries','psychological facts & mind tricks','animal intelligence & behavior','engineering marvels','hidden history nobody talks about','rare natural phenomena','astronomy & space facts','ancient technology & inventions','quantum physics oddities','human brain facts','volcanoes & extreme earth science','secret military projects','lost cities & ruins','survival science & human limits','viral movie facts & behind the scenes','iconic pop culture mysteries explained'];

const wf = $getWorkflowStaticData('global');
if (typeof wf.runCounter !== 'number') wf.runCounter = 0;
wf.runCounter++;
const counter = wf.runCounter;
const category = categories[counter % categories.length];

function fisherYatesSample(arr, n){
  const a = arr.slice();
  const len = Math.min(n, a.length);
  for (let i = a.length - 1; i > a.length - 1 - len; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a.slice(a.length - len);
}

// Strategy: always keep the MOST RECENT items (catches near-term repeats reliably),
// then top it up with a random sample from older history (catches long-tail repeats)
// without ever exceeding a size small/free models can actually read.
function buildBanBlock(list, recentN, randomN){
  const unique = [...new Set(list)];
  const recent = unique.slice(-recentN);
  const older  = unique.slice(0, Math.max(0, unique.length - recentN));
  const randomOlder = fisherYatesSample(older, randomN);
  return [...new Set([...recent, ...randomOlder])];
}

const banListArr   = buildBanBlock([...usedTopics, ...usedTitles], 250, 150); // cap ~400 entries
const hookBanArr    = buildBanBlock(usedHooks, 150, 100);                      // cap ~250 entries
const entityBanArr  = buildBanBlock(usedEntities.flatMap(e => e.split(',').map(x=>x.trim()).filter(Boolean)), 150, 100);
const summaryBanArr = buildBanBlock(usedDescs, 100, 80);                       // feeds AI Semantic Duplicate Check

const banList    = banListArr.join(' | ');
const hookBan     = hookBanArr.join(' | ');
const entityBan   = entityBanArr.join(', ');
const summaryBan  = summaryBanArr.join(' | ');

const trendingContext = wf.trendingContext || '';
const top5UniqueTrends = wf.top5UniqueTrends || [];
const top5Line = top5UniqueTrends.length
  ? 'FRESH UNIQUE ANGLES (top 5, already deduped against the full sheet — prefer these first):\n' + top5UniqueTrends.map((t,i)=>`${i+1}. ${t}`).join('\n')
  : '';

return [{ json: { category, counter, banList, hookBan, entityBan, summaryBan, usedCount: rows.length, trendingContext, top5Line, top5UniqueTrends } }];

function extractBalancedJson(str){
  const start = str.indexOf('{');
  if (start === -1) return null;
  let depth = 0, inStr = false, esc = false;
  for (let i = start; i < str.length; i++) {
    const ch = str[i];
    if (esc) { esc = false; continue; }
    if (ch === '\\' && inStr) { esc = true; continue; }
    if (ch === '"') { inStr = !inStr; continue; }
    if (inStr) continue;
    if (ch === '{') depth++;
    else if (ch === '}') {
      depth--;
      if (depth === 0) return str.slice(start, i + 1);
    }
  }
  return null; // never balanced -> genuinely truncated, let the old repair path handle it
}

function dynamicFallback(){
  const cat = (()=>{ try { return $('Build Exclusion Prompt').first().json.category; } catch(e){ return 'science'; } })();
  const ctr = (()=>{ try { return $('Build Exclusion Prompt').first().json.counter || 0; } catch(e){ return Math.floor(Math.random()*1000); } })();
  const topic = `${cat} fact set ${ctr}`;
  return {
    title: `${ctr%9+1} ${cat.split(' ')[0]} Secrets You Never Knew`,
    topic,
    hook: 'fallback dynamic hook',
    description: `Mind-blowing ${cat} facts you never knew. Follow for daily shorts!`,
    tags: ['science','technology','facts','shorts',cat.split(' ')[0],'future','viral','education','didyouknow','learn'],
    pinnedComment: `Which one surprised you the most about ${cat.split(' ')[0]}?`,
    scenes: [
      { scene:1, voice:`What if everything you believe about ${cat} is completely wrong right now today?`, image_prompt:`cinematic vertical 9:16 dramatic ${cat} scene glowing high contrast photorealistic detailed lighting` },
      { scene:2, voice:`Scientists recently discovered something about ${cat} that quietly changes how we understand the entire world.`, image_prompt:`cinematic vertical 9:16 laboratory discovery ${cat} dramatic lighting photorealistic ultra detailed` },
      { scene:3, voice:`This single hidden detail in ${cat} is far stranger than almost anyone alive today ever imagined.`, image_prompt:`cinematic vertical 9:16 mysterious ${cat} close up dramatic high contrast photorealistic` },
      { scene:4, voice:`Experts still argue about this ${cat} mystery because the real answer sounds almost impossible to believe.`, image_prompt:`cinematic vertical 9:16 intense ${cat} phenomenon glowing dramatic lighting photorealistic detailed` },
      { scene:5, voice:`The truth about ${cat} is only beginning, so follow now and never miss another mind blowing fact.`, image_prompt:`cinematic vertical 9:16 vast dramatic ${cat} reveal glowing cosmos high contrast photorealistic` }
    ]
  };
}

// --- 1) Response extraction: Gemini + OpenRouter/OpenAI দুটোই সাপোর্ট করে ---
let raw = '';
let apiErrorMsg = '';
try { apiErrorMsg = $json?.error?.message ?? ''; } catch(e){ apiErrorMsg = ''; }

try {
  raw = $json?.candidates?.[0]?.content?.parts?.[0]?.text
     ?? $json?.choices?.[0]?.message?.content
     ?? '';
} catch(e){ raw=''; }

// --- 4) API error (429 / empty response ইত্যাদি) লগ করা ---
if (!raw && apiErrorMsg) {
  console.log('API error:', apiErrorMsg);
}

try{ raw=String(raw).replace(/^```json\s*/i,'').replace(/```$/i,'').trim(); }catch(e){ raw=''; }

function tryParse(s){ try{ return JSON.parse(s); }catch(e){ return null; } }

let data=null;
if(raw && raw.length>2){
  data=tryParse(raw);
  // model sometimes adds an extra stray bracket/brace at the very end (or other junk
  // after the object closes) - extract just the first balanced {...} and retry before
  // falling through to the older truncation-repair heuristics below
  if(!data){
    const balanced = extractBalancedJson(raw);
    if (balanced) data = tryParse(balanced);
  }
  if(!data){
    try{
      let fixed=raw;
      fixed=fixed.replace(/,\s*"[^"]*"\s*:\s*"[^"]*$/,'');
      fixed=fixed.replace(/,\s*"[^"]*$/,'');
      fixed=fixed.replace(/,\s*$/,'');
      const oC=(fixed.match(/\{/g)||[]).length,cC=(fixed.match(/\}/g)||[]).length,oB=(fixed.match(/\[/g)||[]).length,cB=(fixed.match(/\]/g)||[]).length;
      fixed+=']'.repeat(Math.max(0,oB-cB));
      fixed+='}'.repeat(Math.max(0,oC-cC));
      data=tryParse(fixed);
    }catch(e){ data=null; }
  }
}

// --- 2) JSON output validation (title/topic/description/tags/scenes) ---
let usedFallback = false;
if(!data || !data.title || !data.topic || !data.description || !Array.isArray(data.tags) || !Array.isArray(data.scenes) || data.scenes.length===0){
  data=dynamicFallback(); usedFallback = true;
}else{
  // --- 3) Scene voice/image validation (আপনার আগের লজিক অপরিবর্তিত) ---
  data.scenes=data.scenes.filter(s=>s&&s.voice&&s.image_prompt).slice(0,5);
  if(data.scenes.length<5){ data=dynamicFallback(); usedFallback = true; }
}

data.scenes=data.scenes.map((s,i)=>({...s,scene:i+1}));

// Never silently ship the canned fallback as if it were a real AI script.
// Flag it so "Script Real?" downstream can send this back through the retry
// loop (advancing to the next model) instead of letting it through.
const wf = $getWorkflowStaticData('global');
if (usedFallback) {
  wf.modelAttempt = (wf.modelAttempt || 0) + 1;
}
const waitSeconds = Math.min(3 + (wf.fullCycles || 0) * 5, 60);

return {json:{
  title:data.title||'Amazing Facts',
  topic:data.topic||data.title||'general',
  hook:data.hook||(data.scenes[0]?data.scenes[0].voice:''),
  description:data.description||(data.title||'Facts'),
  tags:Array.isArray(data.tags)&&data.tags.length?data.tags:['science','technology','shorts'],
  pinnedComment:(data.pinnedComment&&String(data.pinnedComment).trim())||'What surprised you most about this one?',
  scenes:data.scenes,
  usedFallback,
  waitSeconds
}};

const wf = $getWorkflowStaticData('global');
if (typeof wf.dupAttempts !== 'number') wf.dupAttempts = 0;

const data = $json;

// ---------------- helpers ----------------

const STOPWORDS = new Set(['the','a','an','of','in','on','how','why','what','is','are','this','that','to','for','and','or','with','your','you','it','its','was','were','be','can','will','these','those','from','about','into','than','then','so','but','if','as','at','by','not','no','do','does','did','has','have','had','one','ever','most','world','new','updated','latest','version','remastered','revised','recent']);

// words used purely to disguise a repost: sequence numbers, part/series markers, freshness claims
const DISGUISE_WORDS = /\b(part|pt|set|vol|volume|series|episode|ep|no|num|number|chapter|edition|version|v\d*|round|day\d*|week\d*|new|updated|latest|remastered|revised|recent|2024|2025|2026|2027)\b/g;

function stripAccents(s){
  return String(s||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'');
}

// very light stemmer so plural/tense variants collapse to the same root
function stem(w){
  return w
    .replace(/(ing|edly)$/,'')
    .replace(/(ies)$/,'y')
    .replace(/(ed|es)$/,'')
    .replace(/s$/,'')
    .trim();
}

function normalize(s){
  let t = stripAccents(String(s || '')).toLowerCase();
  t = t.replace(/[^a-z0-9\s]/g, ' ');
  t = t.replace(/\b\d+\b/g, ' ');
  t = t.replace(DISGUISE_WORDS, ' ');
  t = t.replace(/\s+/g, ' ').trim();
  return t;
}

function tokens(s){
  return normalize(s)
    .split(' ')
    .filter(w => w.length > 2 && !STOPWORDS.has(w))
    .map(stem)
    .filter(Boolean);
}

// canonical signature: sorted unique stemmed tokens -> catches word-order shuffles
function signature(s){
  return [...new Set(tokens(s))].sort().join(' ');
}

// small non-cryptographic hash for fast fingerprint compare
function hashStr(s){
  let h = 0;
  for (let i = 0; i < s.length; i++) {
    h = (Math.imul(31, h) + s.charCodeAt(i)) | 0;
  }
  return (h >>> 0).toString(36);
}

function jaccard(aTokens, bTokens){
  if (!aTokens.length || !bTokens.length) return 0;
  const a = new Set(aTokens), b = new Set(bTokens);
  let inter = 0;
  for (const w of a) if (b.has(w)) inter++;
  const union = new Set([...a, ...b]).size;
  return union ? inter / union : 0;
}

// word-bigram shingles catch paraphrases/rewrites that swap synonyms but keep sentence flow
function shingles(tokArr, n){
  const out = [];
  for (let i = 0; i <= tokArr.length - n; i++) out.push(tokArr.slice(i, i + n).join('_'));
  return out;
}

function containsOrContained(a, b){
  return a && b && (a === b || a.includes(b) || b.includes(a));
}

// ---------------- gather new content ----------------

const newTopic = String(data.topic || '');
const newTitle = String(data.title || '');
const newHook  = String(data.hook || '');
const newDesc  = String(data.description || '');
const scenes   = Array.isArray(data.scenes) ? data.scenes : [];
const newScript = scenes.map(s => String(s && s.voice || '')).join(' ');

const newTopicNorm = normalize(newTopic);
const newTopicSig  = signature(newTopic);
const newTitleSig  = signature(newTitle);
const newHookSig   = signature(newHook);
const newConceptSig = signature(`${newTopic} ${newTitle} ${newHook}`);

const newTopicTokens   = tokens(newTopic);
const newTitleTokens   = tokens(newTitle);
const newHookTokens    = tokens(newHook);
const newScriptTokens  = tokens(newScript);
const newScriptShingles = shingles(newScriptTokens, 3);

const newFingerprint = hashStr(newConceptSig);
const newScriptFingerprint = hashStr(signature(newScript));

// ---------------- gather history ----------------

let pastEntries = [];
try {
  const rows = $('Read Used Topics').all().map(i => i.json).filter(Boolean);
  pastEntries = rows.map(r => ({
    topic: String(r.topic || ''),
    title: String(r.title || ''),
    hook: String(r.hook || ''),
    description: String(r.description || ''),
    script: String(r.script || '')
  }));
} catch (e) {}

// ---------------- thresholds ----------------

const TITLE_TOPIC_HOOK_THRESHOLD = 0.55;
const CONCEPT_THRESHOLD          = 0.6;   // topic+title+hook combined = "same idea" check
const SCRIPT_THRESHOLD           = 0.5;   // token overlap on full narration
const SCRIPT_SHINGLE_THRESHOLD   = 0.35;  // phrase-level rewrite/paraphrase detector

let isDup = false;
let dupReason = '';
let matchedAgainst = '';

for (const p of pastEntries) {
  const pTopicNorm = normalize(p.topic);

  // Layer 1: exact / substring normalized topic match (catches numbers, prefixes, suffixes, punctuation tricks)
  if (newTopicNorm && pTopicNorm && containsOrContained(newTopicNorm, pTopicNorm)) {
    isDup = true; dupReason = 'normalized-topic-match'; matchedAgainst = p.topic; break;
  }

  // Layer 2: canonical signature exact match (catches reordered words, disguise words, light rewrites)
  const pTopicSig = signature(p.topic);
  const pTitleSig = signature(p.title);
  const pHookSig  = signature(p.hook);
  const pConceptSig = signature(`${p.topic} ${p.title} ${p.hook}`);

  if (newTopicSig && pTopicSig && newTopicSig === pTopicSig) {
    isDup = true; dupReason = 'topic-signature-match'; matchedAgainst = p.topic; break;
  }
  if (newTitleSig && pTitleSig && newTitleSig === pTitleSig) {
    isDup = true; dupReason = 'title-signature-match'; matchedAgainst = p.title; break;
  }

  // Layer 3: fingerprint hash match on combined concept
  if (newFingerprint === hashStr(pConceptSig) && pConceptSig) {
    isDup = true; dupReason = 'concept-fingerprint-match'; matchedAgainst = p.topic; break;
  }

  // Layer 4: token-overlap similarity (title / topic / hook individually)
  const pTopicTokens = tokens(p.topic);
  const pTitleTokens = tokens(p.title);
  const pHookTokens  = tokens(p.hook);

  if (jaccard(newTopicTokens, pTopicTokens) >= TITLE_TOPIC_HOOK_THRESHOLD) { isDup = true; dupReason = 'topic-overlap'; matchedAgainst = p.topic; break; }
  if (jaccard(newTitleTokens, pTitleTokens) >= TITLE_TOPIC_HOOK_THRESHOLD) { isDup = true; dupReason = 'title-overlap'; matchedAgainst = p.title; break; }
  if (newHookTokens.length && jaccard(newHookTokens, pHookTokens) >= TITLE_TOPIC_HOOK_THRESHOLD) { isDup = true; dupReason = 'hook-overlap'; matchedAgainst = p.hook; break; }

  // Layer 5: concept-level overlap (topic+title+hook together) -- catches "same idea, different words everywhere"
  const pConceptTokens = tokens(`${p.topic} ${p.title} ${p.hook}`);
  const newConceptTokens = tokens(`${newTopic} ${newTitle} ${newHook}`);
  if (jaccard(newConceptTokens, pConceptTokens) >= CONCEPT_THRESHOLD) {
    isDup = true; dupReason = 'concept-overlap'; matchedAgainst = p.topic; break;
  }

  // Layer 6: script-level checks (only meaningful once history rows start storing "script")
  if (p.script) {
    const pScriptTokens = tokens(p.script);
    if (newScriptTokens.length && jaccard(newScriptTokens, pScriptTokens) >= SCRIPT_THRESHOLD) {
      isDup = true; dupReason = 'script-overlap'; matchedAgainst = p.topic; break;
    }
    const pScriptShingles = shingles(pScriptTokens, 3);
    if (newScriptShingles.length && jaccard(newScriptShingles, pScriptShingles) >= SCRIPT_SHINGLE_THRESHOLD) {
      isDup = true; dupReason = 'script-phrase-rewrite'; matchedAgainst = p.topic; break;
    }
    if (newScriptFingerprint === hashStr(signature(p.script))) {
      isDup = true; dupReason = 'script-fingerprint-match'; matchedAgainst = p.topic; break;
    }
  }

  // Layer 7: description overlap (thumbnail/description swap disguise)
  if (p.description && newDesc) {
    const pDescTokens = tokens(p.description);
    const newDescTokens = tokens(newDesc);
    if (jaccard(newDescTokens, pDescTokens) >= 0.65) {
      isDup = true; dupReason = 'description-overlap'; matchedAgainst = p.topic; break;
    }
  }
}

const MAX_RETRIES = 5;
let decision = 'ok';
if (isDup) {
  wf.dupAttempts++;
  // after MAX_RETRIES failed unique attempts in a row, let it through rather than stalling the run forever
  decision = (wf.dupAttempts >= MAX_RETRIES) ? 'ok' : 'dup';
} else {
  wf.dupAttempts = 0;
}

return {
  json: {
    ...data,
    decision,
    isDup,
    dupReason,
    matchedAgainst,
    dupAttempts: wf.dupAttempts,
    script: newScript,
    scriptFingerprint: newScriptFingerprint,
    conceptFingerprint: newFingerprint
  }
};

const scene = $json;
const meta = $('Parse JSON').first().json;
const voice = String(scene.voice || '').trim();
const idx = scene.scene || ($itemIndex + 1);
return { json: { idx, voice, image_prompt: scene.image_prompt, title: meta.title, topic: meta.topic, description: meta.description, tags: meta.tags } };

const bin = $binary || {};
const keys = Object.keys(bin);
const idx = $('Prep Scene').first().json.idx;
if (keys.length === 0) { return { json: { hasImage: false, idx }, binary: {} }; }
let key = keys.includes('data') ? 'data' : keys[0];
const b = bin[key];
try { b.fileName = `scene_${idx}.jpg`; } catch(e) {}
const wf = $getWorkflowStaticData('global');
if (wf.imageRetries) wf.imageRetries[idx] = 0;
return { json: { hasImage: true, idx }, binary: { data: b } };

const wf = $getWorkflowStaticData('global');
if (!wf.imageRetries) wf.imageRetries = {};
const idx = $json.idx;
wf.imageRetries[idx] = (wf.imageRetries[idx] || 0) + 1;
const MAX_RETRIES = 3;
const decision = wf.imageRetries[idx] <= MAX_RETRIES ? 'retry' : 'give_up';
return { json: { idx, decision, retryCount: wf.imageRetries[idx] } };

const meta = $('Parse JSON').first().json;
const tags = Array.isArray(meta.tags)?meta.tags:['science','technology','shorts'];
const title=(meta.title||'Amazing Facts').slice(0,95);
const topTags = tags.slice(0,4).map(t=>'#'+String(t).replace(/\s+/g,''));
let description=`${meta.description||title}\n\n#shorts ${topTags.join(' ')}\n\n${tags.map(t=>'#'+String(t).replace(/\s+/g,'')).join(' ')}`;
if(description.length>4900)description=description.slice(0,4900);
let tagList=[],total=0;
for(const t of tags){const s=String(t);if(total+s.length+1>480)break;tagList.push(s);total+=s.length+1;}
if(tagList.length===0)tagList=['science','technology','shorts'];
const currentYear=new Date().getFullYear();const copyrightLine=`\u00a9 ${currentYear} Infinity Entertainment X. All Rights Reserved.\nSubscribe: https://www.youtube.com/@InfinityEntertainmentX`;description=`${description}\n\n${copyrightLine}`;if(description.length>4900)description=description.slice(0,4900);const publishAt=new Date(Date.now()+2*60*60*1000).toISOString();
let pinnedComment=String(meta.pinnedComment||'').trim();if(!pinnedComment)pinnedComment='What surprised you most about this one?';if(pinnedComment.length>200)pinnedComment=pinnedComment.slice(0,200);return {json:{title,topic:meta.topic||title,description,tags:tagList,publishAt,pinnedComment}};

const videoId=$('YouTube Upload (Scheduled)').first().json.id;
let thumbBin=null;
try{ thumbBin=$('Read Thumbnail').first().binary; }catch(e){ thumbBin=null; }
if(!thumbBin){ return {json:{id:videoId,noThumb:true}}; }
return {json:{id:videoId},binary:thumbBin};

const meta=$('Build YT Meta').first().json;
let renderSec='n/a';
try{const fs=require('fs');const start=parseInt(fs.readFileSync('/tmp/render_start','utf8').trim());renderSec=Math.round(Date.now()/1000)-start;}catch(e){}
const videoId=$('YouTube Upload (Scheduled)').first().json.id;
const log={status:'SUCCESS',workflow:'Auto YouTube Shorts (v9)',title:meta.title,topic:meta.topic,videoId,publishAt:meta.publishAt,sceneCount:$('Wait All Scenes').first().json.sceneCount,renderTimeSec:renderSec,pinnedComment:meta.pinnedComment,pinCommentReminder:`Pin this manually in YouTube Studio (auto-pin isn't possible via the API): https://studio.youtube.com/video/${videoId}/comments`,timestamp:new Date().toISOString()};
console.log('[EXEC LOG]',JSON.stringify(log));
return {json:log};

// Fixed: read-only error crash এড়াতে $json থেকে safely field নেওয়া হচ্ছে।
const e = $json || {};
let node='unknown', message='unknown error', wfName='Auto YouTube Shorts';
try { node = e.execution && e.execution.lastNodeExecuted ? e.execution.lastNodeExecuted : 'unknown'; } catch(err){}
try { message = (e.execution && e.execution.error && e.execution.error.message) ? String(e.execution.error.message) : JSON.stringify(e).slice(0,300); } catch(err){ message='error serialization failed'; }
try { wfName = (e.workflow && e.workflow.name) ? e.workflow.name : wfName; } catch(err){}
const log = { status:'FAILED', workflow:wfName, node, message, timestamp:new Date().toISOString() };
console.error('[ERROR LOG]', JSON.stringify(log));
return { json: log };

