parameters.jsCode:
let data = $json;
if (!data || !Array.isArray(data.scenes) || data.scenes.length === 0) {
  const cat = data && (data.topic || data.title) ? (data.topic || data.title) : 'general';
  data = {
    ...data,
    title: (data && data.title) || 'Amazing Facts',
    topic: (data && data.topic) || cat,
    hook: (data && data.hook) || 'fallback dynamic hook',
    description: (data && data.description) || `Mind-blowing ${cat} facts you never knew. Follow for daily shorts!`,
    tags: (data && Array.isArray(data.tags) && data.tags.length) ? data.tags : ['science','technology','facts','shorts','education'],
    scenes: [
      { scene:1, voice:`Here are five surprising facts about ${cat} you probably never knew.`, image_prompt:`cinematic vertical 9:16 dramatic ${cat} scene photorealistic lighting` },
      { scene:2, voice:`Scientists recently discovered something surprising about ${cat}.`, image_prompt:`cinematic vertical 9:16 laboratory discovery ${cat} dramatic lighting photorealistic` },
      { scene:3, voice:`This hidden detail about ${cat} is stranger than most people imagine.`, image_prompt:`cinematic vertical 9:16 mysterious ${cat} close up dramatic photorealistic` },
      { scene:4, voice:`Experts still debate this ${cat} mystery because the answer sounds impossible.`, image_prompt:`cinematic vertical 9:16 intense ${cat} phenomenon glowing dramatic photorealistic` },
      { scene:5, voice:`The story of ${cat} is only beginning, so follow for more.`, image_prompt:`cinematic vertical 9:16 vast dramatic ${cat} reveal glowing photorealistic` }
    ]
  };
} else {
  data = { ...data, scenes: data.scenes.map((s,i)=>({...s, scene: i+1})) };
}
return { json: data };

const original = $('Image Prompt Model Controller').first().json.originalData;

let raw = '';
try {
  raw = $json?.candidates?.[0]?.content?.parts?.map(p => p.text || '').join('') || '';
} catch(e) { raw = ''; }
raw = String(raw || '').replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim();

function tryParse(s){ try { return JSON.parse(s); } catch(e){ return null; } }
const parsed = tryParse(raw);

const scenes = Array.isArray(original.scenes) ? original.scenes : [];
const newPrompts = Array.isArray(parsed?.image_prompts) ? parsed.image_prompts : [];

const mergedScenes = scenes.map((s, i) => {
  const np = newPrompts[i];
  const useNew = np && String(np).trim().length > 10;
  return { ...s, image_prompt: useNew ? String(np).trim() : s.image_prompt };
});

return { json: { ...original, scenes: mergedScenes } };

let aiDup = false;
let aiReason = '';
let aiMatched = '';
try {
  const raw = $json?.candidates?.[0]?.content?.parts?.[0]?.text ?? '';
  const cleaned = String(raw).replace(/^```json\s*/i, '').replace(/```$/i, '').trim();
  const parsed = JSON.parse(cleaned);
  aiDup = !!parsed.duplicate;
  aiReason = String(parsed.reason || '');
  aiMatched = String(parsed.matched || '');
} catch (e) {
  // if the AI check itself fails/errors, do NOT block the pipeline on it -- heuristic Dedupe Check already ran
  aiDup = false;
  aiReason = 'ai-check-unavailable';
}

const prev = $('Dedupe Check').first().json;
const finalIsDup = prev.isDup || aiDup;
const finalDecision = finalIsDup && prev.dupAttempts < 5 ? 'dup' : 'ok';

return {
  json: {
    ...prev,
    aiDup,
    aiReason,
    aiMatched,
    decision: finalDecision
  }
};

const wf = $getWorkflowStaticData('global');
if (typeof wf.modelAttempt !== 'number') wf.modelAttempt = 0;

const cfg = $('Config Center').first().json;

// ---- Build (or reuse) this run's live free-model queue ----
// Fetched ONCE per workflow run (cached on wf.liveModelQueue) so we don't hammer
// OpenRouter's model-list endpoint on every retry inside the same run.
if (!Array.isArray(wf.liveModelQueue)) {
  let liveList = [];
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://openrouter.ai/api/v1/models',
      headers: cfg.openrouterApiKey ? { Authorization: `Bearer ${cfg.openrouterApiKey}` } : {},
      json: true,
      timeout: 15000
    });
    const models = (res && res.data) || [];
    liveList = models
      .filter(m => {
        const p = m.pricing || {};
        const num = v => (v === undefined || v === null || v === '') ? 0 : Number(v);
        // "Fully free" = every pricing field is 0 (prompt, completion, AND any per-request /
        // image / web-search surcharge). Some OpenRouter ":free" models still carry a non-zero
        // request or image fee — those are NOT free and must be excluded so nothing ever costs money.
        const isFree = num(p.prompt) === 0 && num(p.completion) === 0 && num(p.request) === 0 && num(p.image) === 0;
        // DOUBLE-CHECK against OpenRouter's own "free" labeling, in ANY of the ways they write it:
        //   - id ends in ":free"                e.g. "meta-llama/llama-3.3-70b-instruct:free"
        //   - display name has "(free)"         e.g. "NVIDIA: Nemotron 3 Ultra (free)"
        //   - display name has the word "free"  e.g. "OpenAI: GPT OSS 120B (free)" / any other wording
        // If NONE of these say "free" -> skip it, no matter what the pricing looks like.
        // If the pricing above is NOT 0 -> skip it too, no matter what the label says.
        // Both must agree it's free, or it never enters the queue -> never costs money.
        const idStr = String(m.id || '');
        const nameStr = String(m.name || '');
        const isMarkedFree = /:free\b/i.test(idStr) || /\(\s*free\s*\)/i.test(nameStr) || /\bfree\b/i.test(nameStr);
        // keep text-in/text-out chat models only — skip image/audio/embedding-only models
        const modality = (m.architecture && m.architecture.modality) || 'text->text';
        const isText = modality.includes('text');
        return isFree && isMarkedFree && isText;
      })
      // NO re-sorting here on purpose: OpenRouter's /models endpoint already returns models in
      // its own default order (closest thing to their "Most Popular" list) — keep that order as-is
      // instead of re-ranking, so the queue tries them in roughly the same order you'd see on
      // openrouter.ai/models.
      .map(m => ({ type: 'openrouter', model: m.id }));
  } catch (e) {
    liveList = [];
  }

  // Gemini first (best quality), then whatever OpenRouter's live list says is actually
  // free right now. No hardcoded static list anymore — if the live fetch comes back empty
  // (network hiccup, OpenRouter down), the queue is just Gemini for this lap; wf.liveModelQueue
  // gets deleted and re-fetched fresh on the next lap (see "all models in this lap failed" below),
  // so it keeps retrying the live OpenRouter list rather than ever falling back to a fixed model.
  const combined = [
    { type: 'google', model: 'gemini-2.0-flash' },
    { type: 'google', model: 'gemini-2.5-pro' },
    ...liveList
  ];

  // de-dupe by type+model, and cap length so a bad fetch can't create a huge loop
  const seen = new Set();
  wf.liveModelQueue = combined.filter(m => {
    const key = `${m.type}:${m.model}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  }).slice(0, 30);
}

const modelQueue = wf.liveModelQueue;

// all models in this lap failed -> do NOT give up and fall back to a canned script.
// Reset to the top of the queue, re-check what's free on OpenRouter for the next lap,
// and keep going. This loop only ends when a model actually produces a usable script.
if (wf.modelAttempt >= modelQueue.length) {
  wf.modelAttempt = 0;
  wf.fullCycles = (wf.fullCycles || 0) + 1;
  delete wf.liveModelQueue; // re-check what's free on OpenRouter before the next lap
  console.log(`Script generation: lap ${wf.fullCycles} of the model queue produced nothing usable - starting another lap from the top.`);
}

const current = modelQueue[wf.modelAttempt];
const src = $('Build Exclusion Prompt').first().json;
const category = src.category;
const banList = src.banList || '';
const hookBan = src.hookBan || '';
const trending = src.trendingContext || '';
const top5Line = src.top5Line || '';
let policyRewriteNote = '';
try { policyRewriteNote = $('Policy Reject Router').first().json.rewriteNote || ''; } catch(e) { policyRewriteNote = ''; }
const trendLine = [policyRewriteNote, top5Line, trending].filter(Boolean).join('\n\n') || 'none available - proceed with the assigned category';

let obscureTopics = '';
try { obscureTopics = $('Trend & Topic Finder').first().json.obscureTopics || ''; } catch(e) { obscureTopics = ''; }
const obscureLine = obscureTopics
  ? `Optional creative fuel - a few real, randomly-picked reference points (use ONLY if one genuinely fits the category and makes a strong obscure fact; ignore any that don't fit, never force a bad one): ${obscureTopics}`
  : '';

const promptText = cfg.scriptPromptTemplate
  .replace('{{CATEGORY}}', category)
  .replace('{{TRENDLINE}}', trendLine)
  .replace('{{OBSCURELINE}}', obscureLine)
  .replace('{{BANLIST}}', banList)
  .replace('{{HOOKBAN}}', hookBan);

let url, body;
if (current.type === 'google') {
  url = `https://generativelanguage.googleapis.com/v1beta/models/${current.model}:generateContent?key=${cfg.geminiApiKey}`;
  body = {
    contents: [ { parts: [ { text: promptText } ] } ],
    generationConfig: { response_mime_type: 'application/json', maxOutputTokens: 2500, temperature: 1.05, topP: 0.95 }
  };
} else {
  url = 'https://openrouter.ai/api/v1/chat/completions';
  body = {
    model: current.model,
    messages: [ { role: 'user', content: promptText } ],
    temperature: 1.5,
    top_p: 1,
    max_tokens: 2500,
    presence_penalty: 1.2
  };
}

// OpenRouter needs its own Authorization + Referer headers.
// Google auth is injected separately by the node's Header Auth credential, so these stay blank for google.
const authValue = current.type === 'openrouter'
  ? `Bearer ${cfg.openrouterApiKey}`
  : '';
const refererValue = current.type === 'openrouter'
  ? cfg.httpReferer
  : '';

return {
  json: {
    loopStatus: 'continue',
    attempt: wf.modelAttempt,
    modelType: current.type,
    modelName: current.model,
    modelQueueSize: modelQueue.length,
    url,
    body,
    authValue,
    refererValue
  }
};

function extractContent(body){
  try {
    return body?.candidates?.[0]?.content?.parts?.[0]?.text
        ?? body?.choices?.[0]?.message?.content
        ?? '';
  } catch(e){ return ''; }
}

function getFinishReason(body){
  try {
    return body?.candidates?.[0]?.finishReason
        ?? body?.choices?.[0]?.finish_reason
        ?? '';
  } catch(e){ return ''; }
}

const wf = $getWorkflowStaticData('global');
const controller = $('Model Controller').first().json;

const b = $json;
const errMsg = (b && b.error && (b.error.message || JSON.stringify(b.error))) || '';
const text = extractContent(b);
const finishReason = String(getFinishReason(b) || '').toLowerCase();

// reject if: API error, empty/too-short text, output got cut off before finishing
// (common with reasoning models that burn the whole token budget on chain-of-thought
// and never reach the actual JSON), or text that doesn't even contain a '{' so it
// cannot possibly be the JSON we asked for
const looksTruncated = finishReason === 'length' || finishReason === 'max_tokens';
const looksLikeJson = String(text).includes('{');

if (errMsg || !text || String(text).trim().length < 20 || looksTruncated || !looksLikeJson) {
  wf.modelAttempt = (wf.modelAttempt || 0) + 1;
  const waitSeconds = Math.min(3 + (wf.fullCycles || 0) * 5, 60);
  return { json: { decision: 'loop', attempt: wf.modelAttempt, waitSeconds, failedModel: controller.modelName, lastError: errMsg || (looksTruncated ? 'truncated/reasoning-only output' : 'empty or non-JSON content') } };
}

// Reset here because this response passed the shallow checks above. If Parse JSON
// later finds the JSON itself is unusable, IT advances modelAttempt and routes back
// into this same loop for another real try (see Parse JSON + Script Real? below).
wf.modelAttempt = 0;
return { json: { decision: 'success', ...b } };

// FACT-CHECK ONLY pass (grammar handled separately by free LanguageTool step next).
// Falls back to the original Parse JSON output if the checker call failed
// or didn't return usable JSON - never lets a bad checker response break the run.
const original = $('Parse JSON').first().json;

let raw = '';
try {
  raw = $json?.candidates?.[0]?.content?.parts?.map(p => p.text || '').join('') || $json?.choices?.[0]?.message?.content || '';
} catch(e) { raw = ''; }

raw = String(raw || '').replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim();

function tryParse(s){ try { return JSON.parse(s); } catch(e) { return null; } }

let fixed = tryParse(raw);

const valid = fixed && fixed.title && fixed.topic && fixed.description
  && Array.isArray(fixed.tags) && Array.isArray(fixed.scenes)
  && fixed.scenes.length === (original.scenes ? original.scenes.length : 5)
  && fixed.scenes.every(s => s && s.voice && s.image_prompt);

const finalData = valid ? fixed : original;

return { json: {
  title: finalData.title,
  topic: finalData.topic,
  hook: finalData.hook || (finalData.scenes[0] ? finalData.scenes[0].voice : ''),
  description: finalData.description,
  tags: finalData.tags,
  scenes: finalData.scenes.map((s, i) => ({ ...s, scene: i + 1 })),
  factCheckApplied: valid
} };

const scene = $json;
const text = String(scene.image_prompt || '').toLowerCase();
let weather = 'none';
if (/\b(rain|storm|downpour|thunderstorm|monsoon)\b/.test(text)) {
  weather = 'rain';
} else if (/\b(snow|blizzard|winter|frost|frozen)\b/.test(text)) {
  weather = 'snow';
}
return { json: { ...scene, weather } };

const fs = require('fs');
function b64(path){
  try { return fs.readFileSync(path).toString('base64'); } catch(e){ return null; }
}
const frames = ['/tmp/qc_frame_1.jpg','/tmp/qc_frame_2.jpg','/tmp/qc_frame_3.jpg','/tmp/qc_frame_4.jpg','/tmp/qc_frame_5.jpg','/tmp/qc_frame_6.jpg','/tmp/qc_frame_7.jpg','/tmp/qc_frame_8.jpg']
  .map(p => b64(p))
  .filter(Boolean);

let srtText = '';
try { srtText = fs.readFileSync('/tmp/full.srt', 'utf8').slice(0, 3000); } catch(e) { srtText = ''; }

const meta = (() => { try { return $('Parse JSON').first().json; } catch(e){ return {}; } })();
const sceneCount = (() => { try { return $('Wait All Scenes').first().json.sceneCount; } catch(e){ return (meta.scenes ? meta.scenes.length : 5); } })();

if (frames.length === 0) {
  return { json: { skipQC: true, reason: 'no frames extracted', frameCount: 0 } };
}

const promptText = `You are a strict, professional YouTube Shorts video QC reviewer. You are shown ${frames.length} frames sampled in chronological order from a finished vertical short, plus its subtitle (SRT) content and scene count.

Score the video HONESTLY on a 1-10 scale per category. Do NOT default to high scores - most first-pass AI-generated shorts land in the 6-8.5 range. Reserve 9-10 only for genuinely flawless execution, and use 4-6 when you see clear, real problems (poor contrast, misaligned or overlapping subtitles, abrupt or missing scene transitions, static or boring framing, weak hook potential, low visual variety between scenes, artifacts, or illegible text).

CATEGORIES:
1. visual_quality - clarity, composition, lighting, artifacts, framing consistency across frames.
2. editing - implied pacing, visual variety between scenes, overall polish.
3. subtitles - readability, sizing/positioning seen in the frames, timing/segmentation quality and grammar in the SRT text.
4. transitions - how well consecutive frames suggest smooth scene-to-scene flow vs jarring cuts.
5. viewer_retention_potential - hook strength, curiosity and pacing based on frame content and subtitle text, likelihood of holding a viewer to the end.

Scene count: ${sceneCount}
SUBTITLE (SRT) CONTENT:
${srtText || 'not available'}

Return ONLY valid JSON, no markdown, no code fences, in exactly this shape:
{"visual_quality":{"score":0,"feedback":""},"editing":{"score":0,"feedback":""},"subtitles":{"score":0,"feedback":""},"transitions":{"score":0,"feedback":""},"viewer_retention_potential":{"score":0,"feedback":""},"overall":{"score":0,"feedback":""}}
Each feedback must be one short, specific, actionable sentence (max ~20 words). The "overall" score should be a holistic judgment, not a plain average, and its feedback should name the single biggest improvement priority.`;

// Provider-agnostic output - QC Model Controller builds the actual request body
// per-provider (Gemini inline_data vs OpenRouter image_url), since the two free
// vision APIs expect different image formats.
return { json: {
  skipQC: false,
  promptText,
  frames,
  frameCount: frames.length
} };

function extractText(body){
  try { return body?.candidates?.[0]?.content?.parts?.map(p=>p.text||'').join('') ?? body?.choices?.[0]?.message?.content ?? ''; } catch(e) { return ''; }
}

let raw = extractText($json);
try { raw = String(raw).replace(/^```json\s*/i,'').replace(/```$/i,'').trim(); } catch(e){ raw=''; }

function tryParse(s){ try { return JSON.parse(s); } catch(e){ return null; } }

let data = raw ? tryParse(raw) : null;

const cats = ['visual_quality','editing','subtitles','transitions','viewer_retention_potential','overall'];
const valid = data && cats.every(c => data[c] && typeof data[c].score === 'number');

let qcStatus;
if (!valid) {
  qcStatus = 'failed';
  data = {};
  for (const c of cats) data[c] = { score: null, feedback: 'AI QC call failed or returned invalid JSON - not scored this run.' };
  data.overall.feedback = 'QC analysis unavailable this run; video still passed technical checks.';
} else {
  qcStatus = 'ok';
}

const clamp = (n) => (typeof n === 'number' && isFinite(n)) ? Math.max(1, Math.min(10, Math.round(n * 10) / 10)) : null;
for (const c of cats) data[c].score = clamp(data[c].score);

const meta = (() => { try { return $('Parse JSON').first().json; } catch(e){ return {}; } })();

return { json: {
  qcStatus,
  title: meta.title || '',
  topic: meta.topic || '',
  visual_quality: data.visual_quality.score,
  visual_quality_note: data.visual_quality.feedback || '',
  editing: data.editing.score,
  editing_note: data.editing.feedback || '',
  subtitles: data.subtitles.score,
  subtitles_note: data.subtitles.feedback || '',
  transitions: data.transitions.score,
  transitions_note: data.transitions.feedback || '',
  viewer_retention_potential: data.viewer_retention_potential.score,
  viewer_retention_potential_note: data.viewer_retention_potential.feedback || '',
  overall: data.overall.score,
  overall_note: data.overall.feedback || '',
  timestamp: new Date().toISOString()
} };

const meta = (() => { try { return $('Parse JSON').first().json; } catch(e){ return {}; } })();
const note = 'Skipped - no frames could be extracted from final.mp4.';
return { json: {
  qcStatus: 'skipped',
  title: meta.title || '',
  topic: meta.topic || '',
  visual_quality: null, visual_quality_note: note,
  editing: null, editing_note: note,
  subtitles: null, subtitles_note: note,
  transitions: null, transitions_note: note,
  viewer_retention_potential: null, viewer_retention_potential_note: note,
  overall: null, overall_note: 'QC skipped this run; video still passed technical checks.',
  timestamp: new Date().toISOString()
} };

// ⚙️ CONFIG CENTER — single source of truth for API keys, endpoints, and the master script-writing prompt.
// Rotate or replace a key? Change the environment variable in n8n / Render — every node below reads it from
// HERE via $('Config Center').first().json.___ instead of calling $env or hardcoding a value in its own code.
// Nothing else in this workflow should contain a raw API key or a second copy of the script prompt.

return [{
  json: {
    // --- API keys / endpoints (values themselves still live safely in env vars, never in this JSON) ---
    openrouterApiKey: $env.OPENROUTER_API_KEY || '',
    geminiApiKey: $env.GEMINI_API_KEY || '',
    youtubeDataApiKey: $env.YOUTUBE_DATA_API_KEY || '',
    notifyWebhookUrl: $env.NOTIFY_WEBHOOK_URL || '',
    httpReferer: $env.APP_REFERER_URL || 'https://n8n-latest-h80s.onrender.com',

    // Note: the Gemini calls (Fact Model Controller -> Fact AI Request, AI Semantic Duplicate Check,
    // Generate Image Prompts From Script, Video QC Analysis) already share ONE n8n credential
    // ("Header Auth account") set in each node's Authentication field — that is n8n's own
    // centralized, encrypted credential store, which is a safer place for that key than a
    // code node, so it is left as-is on purpose rather than duplicated here.

    // --- Master script-writing prompt (static persona/rules block) ---
    // Model Controller fills in {{CATEGORY}}, {{TRENDLINE}}, {{OBSCURELINE}}, {{BANLIST}}, {{HOOKBAN}}
    // at request time. Edit the writing style/rules ONLY here — not inside Model Controller.
    scriptPromptTemplate: `You are a world-class viral YouTube Shorts scriptwriter for a US audience. Return ONLY valid JSON. No markdown, no code fences.

Create ONE viral Short in category: {{CATEGORY}}.

TRENDING SIGNALS (inspiration only, never copy phrasing, no news/person commentary):
{{TRENDLINE}}

{{OBSCURELINE}}

MEMORY BLACKLIST (never reuse/paraphrase):
Titles/topics: {{BANLIST}}
Hooks: {{HOOKBAN}}

ORIGINALITY: rare, narrow, fresh, specific topic \u2014 never generic. NEVER use these overused cliches/myths or close variants: neutron star teaspoon weighs a billion tons, bananas are radioactive, honey never spoils, octopus has three hearts, great wall of china visible from space, goldfish three second memory, humans only use 10 percent of the brain, vikings wore horned helmets, glass is a slow liquid, venus is the hottest planet, diamonds form from coal, pyramids built by aliens, blood is blue in the body, we swallow our tongue during a seizure \u2014 plus any other pop-science trivia already seen thousands of times on Shorts. NEVER open with generic hook phrasing like 'did you know', 'you won't believe', 'this will blow your mind', 'wait for it', 'scientists say' with no named source. Every script must center on a genuinely obscure, specific, verifiable fact a general audience has not seen repeated on Shorts before. Do NOT dodge the blacklist by appending numbers ("topic 1", "topic 2"), adding part/set/vol/series, reordering words, or lightly rewording a banned title/topic/hook \u2014 the system detects normalized and near-duplicate matches automatically and will reject them. Pick a genuinely different subject instead.\n\nSTRUCTURE: exactly 5 scenes. Scene 1 = shocking question or bold claim, 6-9 words, must create curiosity within the first 0.5 seconds of the line \u2014 no scene-setting, no throat-clearing, never start with 'Did you know', 'Imagine', or 'What if' or any generic intro. Scenes 2-4 each reveal exactly ONE new surprising fact, escalating curiosity \u2014 never explain or summarize, never repeat the previous scene's setting, wording, or angle; each ends on an open curiosity loop that pulls into the next scene. Scene 5 closes the biggest curiosity loop with a twist/payoff line that rewards watching to the end \u2014 NOT a generic 'follow for more' or 'subscribe' CTA; the curiosity payoff itself is the retention driver.

VOICE: one punchy sentence per scene, simple natural US English, 8-12 words each, total script reads aloud in 20-24s at a brisk pace (voice will be rendered ~18% faster than normal TTS speed, so keep sentences tight and avoid long subordinate clauses). LOOP HACK (optional, only if it stays natural - never force it or sacrifice the payoff): phrase scene 5's final clause so it could plausibly continue straight into scene 1's opening words if the video replays, e.g. scene 5 ends '...and the real reason nobody talks about' and scene 1 begins '...this forgotten discovery.' Do not literally repeat scene 1's words in scene 5; just leave the grammar open-ended.\n\nTONE: write like a premium science-documentary narrator (Nat Geo / Nova style) \u2014 precise, vivid, confident word choice, zero filler. Never use flat AI-ish phrasing like 'in the world of', 'when it comes to', \"it's important to note\", \"in today's world\", 'let's dive in'.\n\nIMAGE PROMPT: short rough draft only (a dedicated visual pass refines this later) \u2014 10-15 words, vertical 9:16 photorealistic, matching that scene's voice line.\n\nTITLE: under 60 chars, curiosity driven, include a number, must match content, no full spoiler.
DESCRIPTION: max 30 words natural keywords.
TAGS: exactly 10 lowercase keywords.
TOPIC: short lowercase slug for one main subject.
PINNED COMMENT: one short, casual, curiosity-driven question or either/or poll tied to the topic, under 15 words, written like a real viewer would ask it, to spark reply engagement.

OUTPUT ONLY JSON:
{"title":"","topic":"","hook":"","description":"","tags":[],"pinnedComment":"","scenes":[{"scene":1,"voice":"","image_prompt":""}]}`
  }
}];

// 🚫 POLICY & SAFETY FILTER
// Scans the generated script for language that risks a YouTube policy strike, demonetization,
// or channel ban — and normalizes the text first so a model can't dodge it with a light rewrite
// (leetspeak, extra punctuation, repeated letters, or spacing a word out).
// Add/edit banned terms in banRules ONLY — keep it current with YouTube's policies and your own strike history.

const d = $json;

const rawText = [
  d.title, d.hook, d.description, d.pinnedComment,
  ...(Array.isArray(d.tags) ? d.tags : []),
  ...(Array.isArray(d.scenes) ? d.scenes.map(s => s.voice) : [])
].filter(Boolean).join(' \n ');

function normalize(str) {
  let s = String(str).toLowerCase();
  s = s.normalize('NFD').replace(/[\u0300-\u036f]/g, '');   // strip accents
  const leet = { '0': 'o', '1': 'i', '3': 'e', '4': 'a', '5': 's', '7': 't', '@': 'a', '$': 's' };
  s = s.replace(/[013457@$]/g, ch => leet[ch] || ch);          // leetspeak -> letters
  s = s.replace(/[^a-z0-9\s]/g, ' ');                          // strip punctuation/symbols
  s = s.replace(/(.)\1{2,}/g, '$1$1');                         // collapse 3+ repeated chars
  s = s.replace(/\s+/g, ' ').trim();
  return s;
}

const normalized = normalize(rawText);
const squashed = normalized.replace(/\s+/g, '');               // catches "k i l l" style spaced-out bypass tricks

const banRules = [
  { category: 'graphic violence / gore',   terms: ['decapitat', 'gutted alive', 'torture method', 'mutilat', 'dismember'] },
  { category: 'self-harm / suicide',       terms: ['suicide method', 'how to kill yourself', 'self harm technique'] },
  { category: 'dangerous acts / weapons',  terms: ['bomb making', 'build a weapon', 'how to make a gun', 'improvised explosive'] },
  { category: 'medical misinformation',    terms: ['cures cancer', 'vaccines cause autism', 'miracle cure', 'doctors dont want you to know'] },
  { category: 'hate / harassment',         terms: ['go kill yourself', 'subhuman'] },
  { category: 'illegal drugs / synthesis', terms: ['drug synthesis', 'how to make meth', 'how to cook meth'] },
  { category: 'child safety',              terms: ['child abuse', 'csam'] }
  // 👉 add more categories/terms here as you learn what trips YouTube's system for your channel
];

const flags = [];
for (const rule of banRules) {
  for (const term of rule.terms) {
    const t = normalize(term);
    const tSquashed = t.replace(/\s+/g, '');
    if (normalized.includes(t) || squashed.includes(tSquashed)) {
      flags.push({ category: rule.category, term });
    }
  }
}

const policySafe = flags.length === 0;

return {
  json: {
    ...d,
    policySafe,
    policyFlags: flags,
    policyCheckedAt: new Date().toISOString()
  }
};

// TOP 5 UNIQUE TRENDS — dedupe candidate trend/topic strings against the FULL
// Google Sheet history (Read Used Topics), then hand the Script Writer a short,
// clean, token-light list of the 5 freshest angles instead of one giant blob.

const wf = $getWorkflowStaticData('global');

// All rows from the Google Sheet (every used topic, ever) — checked in FULL, not partially.
const sheetRows = $('Read Used Topics').all().map(i => i.json).filter(Boolean);

function norm(s) {
  return String(s || '')
    .toLowerCase()
    .normalize('NFKD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

// Build the FULL used-history set (title + topic) — nothing skipped, whole sheet checked.
const usedSet = new Set();
for (const r of sheetRows) {
  const t1 = norm(r.title);
  const t2 = norm(r.topic);
  if (t1) usedSet.add(t1);
  if (t2) usedSet.add(t2);
}

// Candidate trend/topic strings pulled from Trend & Topic Finder (YouTube + Google Trends + Wikipedia).
const trendNode = (() => { try { return $('Trend & Topic Finder').first().json; } catch (e) { return {}; } })();
const candidates = [
  ...(Array.isArray(trendNode.youtubeTrends) ? trendNode.youtubeTrends : []),
  ...(Array.isArray(trendNode.googleTrends) ? trendNode.googleTrends : []),
  ...(String(trendNode.obscureTopics || '').split(',').map(s => s.trim()).filter(Boolean))
];

// 1) Remove duplicates within the candidate list itself (case/spacing-insensitive).
const seenLocal = new Set();
const localUnique = [];
for (const c of candidates) {
  const key = norm(c);
  if (!key || seenLocal.has(key)) continue;
  seenLocal.add(key);
  localUnique.push(c);
}

// 2) Remove anything already used before (checked against the FULL sheet, not a sample).
const freshOnly = localUnique.filter(c => !usedSet.has(norm(c)));

// 3) Take the Top 5 unique/fresh items only — keeps the prompt short so the AI spends
//    fewer tokens reading context and more on writing the actual script.
const top5 = freshOnly.slice(0, 5);

// Store for Build Exclusion Prompt / Model Controller to read (kept out of the big ban-list).
wf.top5UniqueTrends = top5;

return [{
  json: {
    top5UniqueTrends: top5,
    top5Line: top5.length ? top5.map((t, i) => `${i + 1}. ${t}`).join('\n') : 'None — go fully original.',
    candidatesSeen: candidates.length,
    duplicatesRemoved: candidates.length - freshOnly.length,
    usedTopicsCheckedInSheet: sheetRows.length
  }
}];

// FREE GRAMMAR PASS — applies LanguageTool's top suggested replacement for each
// detected spelling/grammar match directly onto the script's voice lines.
// LanguageTool only flags grammar/spelling (no fact-checking) — that's handled
// separately upstream by the AI fact-checker. If the API failed or returned
// nothing usable, this safely falls back to the untouched script.

const original = $('Apply Fact Check Fixes').first().json;
const scenes = Array.isArray(original.scenes) ? original.scenes.slice() : [];

let matches = [];
try {
  matches = Array.isArray($json.matches) ? $json.matches : [];
} catch (e) {
  matches = [];
}

if (!matches.length || !scenes.length) {
  return { json: { ...original, grammarFixApplied: false } };
}

// Rebuild the same joined text LanguageTool Grammar Check sent, so match offsets line up.
const joined = scenes.map((s, i) => `[[${i}]] ${s.voice || ''}`).join(' \n ');

// Apply replacements back-to-front so earlier offsets stay valid as we edit.
const sorted = matches.slice().sort((a, b) => b.offset - a.offset);
let corrected = joined;
for (const m of sorted) {
  const rep = m.replacements && m.replacements[0] && m.replacements[0].value;
  if (!rep) continue;
  const start = m.offset;
  const end = m.offset + m.length;
  corrected = corrected.slice(0, start) + rep + corrected.slice(end);
}

// Split back into per-scene voice lines using the [[i]] markers.
const parts = corrected.split(/\[\[(\d+)\]\]/).slice(1); // ["0", " text ", "1", " text ", ...]
const fixedByIndex = {};
for (let i = 0; i < parts.length; i += 2) {
  const idx = parseInt(parts[i], 10);
  const text = (parts[i + 1] || '').trim();
  if (!Number.isNaN(idx) && text) fixedByIndex[idx] = text;
}

const newScenes = scenes.map((s, i) => ({
  ...s,
  voice: fixedByIndex[i] || s.voice
}));

return { json: { ...original, scenes: newScenes, grammarFixApplied: true, grammarMatchesFound: matches.length } };

