Return ONLY valid JSON:
{"duplicate": true, "confidence": 0.97, "duplicate_type": "same_fact", "reason": "same scientific fact explained differently", "matched": ["Title A", "Title B"]}

duplicate_type must be one of: same_fact, same_story, same_history, same_science, same_person, same_biography, same_comparison, same_ranking, same_myth, same_explanation, same_conclusion, same_topic, different.
Confidence must be between 0 and 1. If uncertain, choose duplicate=true.`;

let url, body;
if (current.type === 'google') {
  url = `https://generativelanguage.googleapis.com/v1beta/models/${current.model}:generateContent?key=${cfg.geminiApiKey}`;
  body = { contents: [ { parts: [ { text: promptText } ] } ], generationConfig: { response_mime_type: 'application/json', temperature: 0, topP: 0.9, maxOutputTokens: 350 } };
} else {
  url = 'https://openrouter.ai/api/v1/chat/completions';
  body = { model: current.model, messages: [ { role: 'user', content: promptText } ], temperature: 0, max_tokens: 350 };
}

const authValue = current.type === 'openrouter' ? `Bearer ${cfg.openrouterApiKey}` : '';
const refererValue = current.type === 'openrouter' ? cfg.httpReferer : '';

return { json: { attempt: wf.semanticAttempt, modelType: current.type, modelName: current.model, url, body, authValue, refererValue } };

// SEMANTIC VALIDATE ATTEMPT — same retry-on-failure pattern as the other finders.
function extractContent(body){
  try { return body?.candidates?.[0]?.content?.parts?.map(p=>p.text||'').join('') ?? body?.choices?.[0]?.message?.content ?? ''; } catch(e){ return ''; }
}
function getFinishReason(body){
  try { return body?.candidates?.[0]?.finishReason ?? body?.choices?.[0]?.finish_reason ?? ''; } catch(e){ return ''; }
}

const wf = $getWorkflowStaticData('global');
const controller = $('Semantic Model Controller').first().json;
const b = $json;

const errMsg = (b && b.error && (b.error.message || JSON.stringify(b.error))) || '';
const text = extractContent(b);
const finishReason = String(getFinishReason(b) || '').toLowerCase();
const looksTruncated = finishReason === 'length' || finishReason === 'max_tokens';
const looksLikeJson = String(text).includes('{');

if (errMsg || !text || String(text).trim().length < 10 || looksTruncated || !looksLikeJson) {
  wf.semanticAttempt = (wf.semanticAttempt || 0) + 1;
  if (wf.semanticAttempt >= 3) {
    // 3 free models in a row failed - give up gracefully instead of looping forever.
    // Merge Semantic Result already treats unparseable input as "not duplicate",
    // so this safely falls through to trusting the heuristic Dedupe Check alone.
    wf.semanticAttempt = 0;
    return { json: { decision: 'giveup' } };
  }
  return { json: { decision: 'retry', failedModel: controller.modelName, lastError: errMsg || (looksTruncated ? 'truncated' : 'empty/non-JSON') } };
}

wf.semanticAttempt = 0;
return { json: { decision: 'success', ...b } };

// QC MODEL CONTROLLER — live free VISION-model discovery, own separate queue
// (wf.qcModelQueue / wf.qcModelAttempt). Filters OpenRouter's free list down
// to models that actually accept image input, since this call sends frames.

const wf = $getWorkflowStaticData('global');
if (typeof wf.qcModelAttempt !== 'number') wf.qcModelAttempt = 0;

const cfg = $('Config Center').first().json;
const built = $('Build QC Vision Request').first().json;

if (built.skipQC) {
  return { json: { skipQC: true, reason: built.reason || 'no frames' } };
}

if (!Array.isArray(wf.qcModelQueue)) {
  let liveList = [];
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://openrouter.ai/api/v1/models',
      headers: cfg.openrouterApiKey ? { Authorization: `Bearer ${cfg.openrouterApiKey}` } : {},
      json: true,
      timeout: 15000
    });
    const models = (res && res.data) || [];
    liveList = models
      .filter(m => {
        const p = m.pricing || {};
        const num = v => (v === undefined || v === null || v === '') ? 0 : Number(v);
        const isFree = num(p.prompt) === 0 && num(p.completion) === 0 && num(p.request) === 0 && num(p.image) === 0;
        const idStr = String(m.id || '');
        const nameStr = String(m.name || '');
        const isMarkedFree = /:free\b/i.test(idStr) || /\(\s*free\s*\)/i.test(nameStr) || /\bfree\b/i.test(nameStr);
        // VISION REQUIRED - this call sends image frames, so a text-only free
        // model would just fail on every attempt. Only keep models whose
        // input modality includes image.
        const inputMods = (m.architecture && m.architecture.input_modalities) || [];
        const modalityStr = (m.architecture && m.architecture.modality) || '';
        const isVision = (Array.isArray(inputMods) && inputMods.includes('image')) || /image/i.test(modalityStr);
        return isFree && isMarkedFree && isVision;
      })
      .map(m => ({ type: 'openrouter', model: m.id }));
  } catch (e) {
    liveList = [];
  }

  const combined = [
    { type: 'google', model: 'gemini-2.0-flash' },
    ...liveList
  ];

  const seen = new Set();
  wf.qcModelQueue = combined.filter(m => {
    const key = `${m.type}:${m.model}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  }).slice(0, 15);
}

const modelQueue = wf.qcModelQueue;

if (wf.qcModelAttempt >= modelQueue.length) {
  // Every free vision model failed this lap - give up gracefully rather than
  // looping forever. Parse QC Result already handles "no valid response" by
  // marking QC as unavailable-but-passed, so this never blocks an upload.
  wf.qcModelAttempt = 0;
  delete wf.qcModelQueue;
  return { json: { skipQC: true, reason: 'all free vision models failed this run' } };
}

const current = modelQueue[wf.qcModelAttempt];
const promptText = built.promptText;
const frames = built.frames || [];

let url, body;
if (current.type === 'google') {
  const parts = [{ text: promptText }];
  for (const f of frames) parts.push({ inline_data: { mime_type: 'image/jpeg', data: f } });
  url = `https://generativelanguage.googleapis.com/v1beta/models/${current.model}:generateContent?key=${cfg.geminiApiKey}`;
  body = { contents: [ { parts } ], generationConfig: { response_mime_type: 'application/json', maxOutputTokens: 900, temperature: 0.4 } };
} else {
  // OpenRouter/OpenAI-style vision format: content is an array mixing text and image_url data-URIs.
  const content = [{ type: 'text', text: promptText }];
  for (const f of frames) content.push({ type: 'image_url', image_url: { url: `data:image/jpeg;base64,${f}` } });
  url = 'https://openrouter.ai/api/v1/chat/completions';
  body = { model: current.model, messages: [ { role: 'user', content } ], temperature: 0.4, max_tokens: 900 };
}

const authValue = current.type === 'openrouter' ? `Bearer ${cfg.openrouterApiKey}` : '';
const refererValue = current.type === 'openrouter' ? cfg.httpReferer : '';

return { json: { skipQC: false, attempt: wf.qcModelAttempt, modelType: current.type, modelName: current.model, modelQueueSize: modelQueue.length, url, body, authValue, refererValue } };

// QC VALIDATE — reject errors/empty/truncated and retry with the next free
// vision model; after all models in the queue are exhausted, QC Model
// Controller already returns skipQC=true on the NEXT call, so this simply
// increments the attempt counter and loops back.

function extractContent(body){
  try { return body?.candidates?.[0]?.content?.parts?.map(p=>p.text||'').join('') ?? body?.choices?.[0]?.message?.content ?? ''; } catch(e){ return ''; }
}
function getFinishReason(body){
  try { return body?.candidates?.[0]?.finishReason ?? body?.choices?.[0]?.finish_reason ?? ''; } catch(e){ return ''; }
}

const wf = $getWorkflowStaticData('global');
const b = $json;
const errMsg = (b && b.error && (b.error.message || JSON.stringify(b.error))) || '';
const text = extractContent(b);
const finishReason = String(getFinishReason(b) || '').toLowerCase();
const looksTruncated = finishReason === 'length' || finishReason === 'max_tokens';
const looksLikeJson = String(text).includes('{');

if (errMsg || !text || String(text).trim().length < 10 || looksTruncated || !looksLikeJson) {
  wf.qcModelAttempt = (wf.qcModelAttempt || 0) + 1;
  return { json: { decision: 'retry' } };
}

wf.qcModelAttempt = 0;
return { json: { decision: 'success', ...b } };
